import{_ as e,o,c as a,a2 as s}from"./chunks/framework.DQ4Fc4vT.js";const r="/tackora/screenshots/board.png",n="/tackora/screenshots/ticket.png",i="/tackora/screenshots/ask.png",d="/tackora/screenshots/usage.png",w=JSON.parse('{"title":"How it works","description":"","frontmatter":{},"headers":[],"relativePath":"guide/how-it-works.md","filePath":"guide/how-it-works.md","lastUpdated":1790183326000}'),h={name:"guide/how-it-works.md"};function l(c,t,g,u,p,k){return o(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h1><p>Tackora is a Kanban board for coding agents. Every ticket is one agent session: the real CLI (Claude Code or OpenCode 2) running in a terminal inside the ticket. The board shows what each agent is doing, and moves the cards as the work progresses.</p><p>This page describes the design. What&#39;s built so far is in <a href="#status">Status</a>.</p><h2 id="the-board" tabindex="-1">The board <a class="header-anchor" href="#the-board" aria-label="Permalink to &quot;The board&quot;">​</a></h2><p><img src="'+r+'" alt="The board"></p><p>Tickets are cards in five columns: <strong>Open</strong>, <strong>In progress</strong>, <strong>Needs review</strong>, <strong>Changes requested</strong> and <strong>Resolved</strong>. Closed tickets are hidden. The same tickets are also a filterable list, and a journal of what happened each day.</p><p>Each card has two pieces of information:</p><ul><li><strong>Its column:</strong> where the work stands.</li><li><strong>Its agent badge:</strong> what the agent is doing right now.</li></ul><table tabindex="0"><thead><tr><th>Badge</th><th>Meaning</th></tr></thead><tbody><tr><td>Running</td><td>The agent is working on your last prompt.</td></tr><tr><td>Done</td><td>The agent finished its turn and is idle at its prompt. Reply whenever you like.</td></tr><tr><td>Needs permission</td><td>The agent is blocked, asking to run a command or edit a file. This is the only state that counts as &quot;needs you&quot;.</td></tr><tr><td>Not running</td><td>No terminal is open. Opening the ticket resumes the session.</td></tr></tbody></table><p>When an agent is <strong>Done</strong> or <strong>Needs permission</strong> while Tackora is in the background, you get a desktop notification.</p><p>The sidebar&#39;s <strong>Active</strong> list shows every ticket whose agent is working or waiting, with the ones that need you first, so you can jump between agents without going back to the board. Pin any ticket (the pin button next to its title) to keep it under <strong>Pinned</strong>.</p><p>New to Tackora? A <strong>Getting started</strong> checklist above the board walks you through adding a project, creating and starting a ticket, and trying <kbd>Ctrl</kbd>+<kbd>K</kbd>. Each step ticks itself off as you do it.</p><h3 id="cards-move-on-their-own" tabindex="-1">Cards move on their own <a class="header-anchor" href="#cards-move-on-their-own" aria-label="Permalink to &quot;Cards move on their own&quot;">​</a></h3><table tabindex="0"><thead><tr><th>When</th><th>The card moves to</th></tr></thead><tbody><tr><td>You send the agent its first prompt</td><td>In progress</td></tr><tr><td>You submit for review and the pull request opens</td><td>Needs review</td></tr><tr><td>A reviewer requests changes on the pull request</td><td>Changes requested</td></tr><tr><td>The agent starts working on those changes</td><td>In progress</td></tr><tr><td>The pull request is merged, in Tackora or on GitHub</td><td>Resolved (the worktree is removed)</td></tr><tr><td>You commit with <strong>Finish</strong> ticked (direct mode)</td><td>Resolved</td></tr></tbody></table><p>You can always drag a card yourself. Dragging to <strong>Needs review</strong> submits it for review, and dragging to <strong>Resolved</strong> merges it (Tackora asks first). Other moves just change the column.</p><h2 id="tickets-are-sessions" tabindex="-1">Tickets are sessions <a class="header-anchor" href="#tickets-are-sessions" aria-label="Permalink to &quot;Tickets are sessions&quot;">​</a></h2><p><img src="'+n+'" alt="A ticket with its agent&#39;s terminal"></p><p>Starting a ticket starts its agent session. Tackora chooses the session&#39;s ID before the agent starts, so every session is tied to its ticket exactly. Reopening the ticket later, even after restarting Tackora, resumes the same session with its full history.</p><ul><li><strong>Claude Code</strong> starts with <code>claude --session-id &lt;id&gt;</code> and resumes with <code>claude --resume &lt;id&gt;</code>.</li><li><strong>OpenCode 2</strong> gets its session created through OpenCode&#39;s local server with Tackora&#39;s ID and the ticket attached, then opens with <code>opencode &lt;folder&gt; --session &lt;id&gt;</code>.</li></ul><p>When you start a ticket you choose the model, the effort level (Claude) or model variant (OpenCode), and the permission mode (Claude) or agent (OpenCode). Defaults come from settings. After that, change them inside the agent as usual; the ticket shows what&#39;s actually in use. To switch agents, use <strong>Start over</strong>, which begins a new session and keeps the old one&#39;s cost in the ticket&#39;s history.</p><p>Have a quick question that isn&#39;t really a task? Create a quick ticket with just a prompt.</p><h2 id="direct-or-worktree" tabindex="-1">Direct or worktree <a class="header-anchor" href="#direct-or-worktree" aria-label="Permalink to &quot;Direct or worktree&quot;">​</a></h2><p>Each ticket runs in one of two ways. Direct is the default, and each project can set its own default.</p><table tabindex="0"><thead><tr><th></th><th>Direct (default)</th><th>Worktree</th></tr></thead><tbody><tr><td>Where the agent works</td><td>The project folder, on whatever branch is checked out (e.g. <code>main</code>)</td><td>A separate folder with a new branch for this ticket</td></tr><tr><td>Several tickets on one project at once</td><td>One running at a time, so two agents don&#39;t edit the same files</td><td>Yes</td></tr><tr><td>When you&#39;re done</td><td><strong>Commit</strong>, optionally push, and tick <strong>Finish</strong> to resolve</td><td><strong>Submit for review</strong> opens a pull request. Merging it resolves the ticket.</td></tr></tbody></table><p>Worktree branches are named from the ticket, like <code>fix/login-throttle</code> or <code>feat/export-csv</code>. You can edit the name and the base branch when you create the ticket.</p><h2 id="ask-tackora" tabindex="-1">Ask Tackora <a class="header-anchor" href="#ask-tackora" aria-label="Permalink to &quot;Ask Tackora&quot;">​</a></h2><p>Press <kbd>Ctrl</kbd>+<kbd>K</kbd> and type what you want in plain words:</p><p><img src="'+i+'" alt="Ask Tackora"></p><ul><li>&quot;Clone anas1412/api and add it as a project&quot;</li><li>&quot;Add a ticket to web: the signup button does nothing on Safari&quot;</li><li>&quot;What&#39;s waiting for me?&quot;</li><li>&quot;Move all the docs tickets in api to Closed&quot;</li></ul><p>Tackora doesn&#39;t have its own AI. It gives your agent (Claude Code or OpenCode) a set of Tackora tools: list and create projects and tickets, edit them, move cards, start sessions. The agent then does what you asked and replies under the command bar, and the cards it changed are highlighted. Press <strong>Continue</strong> to follow up.</p><p>Agents working on tickets get the same tools. In any ticket&#39;s terminal you can say &quot;add a follow-up ticket for the signup form&quot;, and an agent can file a ticket itself when it spots another problem. Every change records who made it (you, the command bar, or the agent on ticket #7).</p><p>Anything destructive or that touches Git waits for you: deleting, removing a project, submitting for review, merging, or changing more than five tickets at once. Tackora shows what&#39;s being asked and who&#39;s asking, and nothing happens until you click <strong>Allow</strong>.</p><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><p>When Tackora starts, it looks for <code>claude</code> and <code>opencode</code> on your PATH:</p><table tabindex="0"><thead><tr><th></th><th>Claude Code</th><th>OpenCode</th></tr></thead><tbody><tr><td>Version</td><td>any</td><td>2.x only. OpenCode 1 counts as not installed.</td></tr><tr><td>Signed in</td><td>required</td><td>optional: OpenCode has free built-in models</td></tr></tbody></table><ul><li><strong>Neither usable:</strong> Tackora shows a setup screen with install commands and a <strong>Re-check</strong> button, and nothing else.</li><li><strong>One usable:</strong> it&#39;s used everywhere.</li><li><strong>Both usable:</strong> pick a default in settings and override it per ticket.</li></ul><h2 id="cost-and-usage" tabindex="-1">Cost and usage <a class="header-anchor" href="#cost-and-usage" aria-label="Permalink to &quot;Cost and usage&quot;">​</a></h2><p>Tackora uses what the agents themselves report:</p><ul><li><strong>Claude Code:</strong> hooks say when a prompt starts and when Claude finishes. The status line reports cost, context usage, and your plan&#39;s 5-hour and 7-day limits.</li><li><strong>OpenCode 2:</strong> its local server streams events for each session: running, finished, cost and tokens.</li></ul><p>Costs add up per ticket, per project and per day on the Usage page.</p><p><img src="'+d+'" alt="The Usage page"></p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>State</th></tr></thead><tbody><tr><td>Embedded terminal, Linux and Windows</td><td>Built · tested in CI on both</td></tr><tr><td>Agent detection and setup screen</td><td>Built</td></tr><tr><td>Projects, tickets, Kanban board, list, journal</td><td>Built</td></tr><tr><td>Tickets as sessions, agent badges, notifications</td><td>Built · tested end to end with both agents on Linux</td></tr><tr><td>Direct and worktree modes</td><td>Built · tested end to end on Linux</td></tr><tr><td>Automatic card moves, submit for review, merge</td><td>Built</td></tr><tr><td>Cost and usage, Claude plan limits</td><td>Built · tested end to end with both agents</td></tr><tr><td>Ask Tackora (command bar, agent tools)</td><td>Built · tested end to end with both agents</td></tr><tr><td>Installers (AppImage, .deb, .rpm, Windows setup)</td><td>Built by CI and on each release tag</td></tr><tr><td>Windows, on a real machine</td><td>Not yet tested by hand</td></tr><tr><td>Code signing, auto-update</td><td>Not yet</td></tr></tbody></table>',43)])])}const b=e(h,[["render",l]]);export{w as __pageData,b as default};
